<?php declare(strict_types=1); namespace App\Controller; use Cake\Http\Response; class AsignacionesParqueaderosController extends AppController { public function index():?Response {$this->set('items',$this->AsignacionesParqueaderos->find()->contain(['Parqueaderos','Residentes','Viviendas'])->all());return null;} public function add():?Response {$item=$this->AsignacionesParqueaderos->newEmptyEntity();if($this->request->is('post')){$item=$this->AsignacionesParqueaderos->patchEntity($item,$this->request->getData());if($this->AsignacionesParqueaderos->save($item))return $this->redirect(['action'=>'index']);}$this->set(compact('item'));$this->lists($item->vivienda_id ? (int)$item->vivienda_id : null);return null;} public function edit(int $id):?Response {$item=$this->AsignacionesParqueaderos->get($id);if($this->request->is(['post','put','patch'])){$item=$this->AsignacionesParqueaderos->patchEntity($item,$this->request->getData());if($this->AsignacionesParqueaderos->save($item))return $this->redirect(['action'=>'index']);}$this->set(compact('item'));$this->lists($item->vivienda_id ? (int)$item->vivienda_id : null);return null;} private function lists(?int $viviendaId = null):void {$this->set('parqueaderos',$this->fetchTable('Parqueaderos')->find('list')->all());$viviendaCode='';if($viviendaId!==null){$vivienda=$this->fetchTable('Viviendas')->find()->select(['code'])->where(['id'=>$viviendaId])->first();$viviendaCode=$vivienda?->code??'';}$this->set(compact('viviendaCode'));} }
